const express = require('express');
const { asyncHandler } = require('../middleware/errorHandler');
const logger = require('../utils/logger');
const { verifyAdminCredentials, normalizeUsername } = require('../services/adminWhitelistService');
const {
  requireAdminSession,
  requireAdminRole,
  requireAdminCsrf,
  issueCsrfToken,
} = require('../middleware/adminSessionAuth');

const router = express.Router();

const isProdEnv = String(process.env.NODE_ENV || '').toLowerCase() === 'production';
const normalizeSameSite = (value) => {
  const raw = (value || '').toString().trim().toLowerCase();
  if (!raw) return 'lax';
  if (raw === 'lax' || raw === 'strict' || raw === 'none') return raw;
  return 'lax';
};

const regenerateSession = (req) => new Promise((resolve, reject) => {
  if (!req.session || typeof req.session.regenerate !== 'function') {
    resolve();
    return;
  }
  req.session.regenerate((err) => {
    if (err) reject(err);
    else resolve();
  });
});

const destroySession = (req) => new Promise((resolve) => {
  if (!req.session || typeof req.session.destroy !== 'function') {
    resolve();
    return;
  }
  req.session.destroy(() => resolve());
});

router.post('/login', asyncHandler(async (req, res) => {
  const username = normalizeUsername(req.body && req.body.username);
  const password = (req.body && req.body.password) || '';
  const passwordText = String(password);

  if (!username || !passwordText.trim()) {
    res.status(400).json({ success: false, error: 'Missing username or password' });
    return;
  }

  if (passwordText.length > 512) {
    res.status(400).json({ success: false, error: 'Invalid credentials' });
    return;
  }

  const admin = await verifyAdminCredentials(username, passwordText);
  if (!admin) {
    // Avoid leaking which field was wrong.
    res.status(401).json({ success: false, error: 'Invalid credentials' });
    return;
  }

  await regenerateSession(req);

  req.session.admin = {
    username: admin.username,
    roles: admin.roles,
    authenticatedAt: new Date().toISOString(),
  };

  const csrfToken = issueCsrfToken(req);

  logger.info('Admin login', { username: admin.username, ip: req.ip });

  res.json({
    success: true,
    admin: { username: admin.username, roles: admin.roles },
    csrfToken,
  });
}));

router.post('/logout', requireAdminSession, requireAdminRole('admin', 'moderator'), requireAdminCsrf, asyncHandler(async (req, res) => {
  const username = req.admin && req.admin.username;
  await destroySession(req);
  try {
    const cookieName = process.env.ADMIN_SESSION_COOKIE_NAME || 'kubus_admin_sid';
    const domain = (process.env.ADMIN_SESSION_COOKIE_DOMAIN || '').trim() || undefined;
    for (const path of ['/api', '/api/admin']) {
      res.clearCookie(cookieName, {
        path,
        domain,
        sameSite: normalizeSameSite(process.env.ADMIN_SESSION_SAMESITE),
        secure: isProdEnv,
      });
    }
  } catch (_) {}
  logger.info('Admin logout', { username, ip: req.ip });
  res.json({ success: true });
}));

router.get('/me', requireAdminSession, requireAdminRole('admin', 'moderator'), asyncHandler(async (req, res) => {
  // Provide a CSRF token so the admin UI can recover if its cached token is missing/stale.
  const csrfToken = (req.session && req.session.csrfToken) || issueCsrfToken(req);
  res.json({
    success: true,
    admin: { username: req.admin.username, roles: req.admin.roles || [] },
    csrfToken,
  });
}));

router.post('/csrf/rotate', requireAdminSession, requireAdminRole('admin', 'moderator'), requireAdminCsrf, asyncHandler(async (req, res) => {
  const csrfToken = issueCsrfToken(req);
  res.json({ success: true, csrfToken });
}));

module.exports = router;
